select s.region, case when year(s.opened_date) < 2024 then 'before_2024' when year(s.opened_date) = 2024 then '2024' else 'after_2024' end as opened_cohort, count(ss.units) as units_count, min(ss.sale_date) as min_sale_date from store_sales ss inner join products p on ss.product_id = p.id inner join stores s on ss.store_id = s.id where ss.revenue <= 3300 group by s.region, case when year(s.opened_date) < 2024 then 'before_2024' when year(s.opened_date) = 2024 then '2024' else 'after_2024' end having count(ss.units) > 4 order by s.region
